import { useState, useCallback } from 'react';
import React from 'react';

/**
 * Hook de notification toast — remplace les alert() incompatibles Capacitor Android.
 *
 * Usage :
 *   const { showToast, ToastUI } = useToast();
 *   showToast("Message de succès");
 *   showToast("Erreur !", "error");
 *   showToast("Attention !", "warning");
 *   // Dans le JSX : {ToastUI}
 */
export function useToast() {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  }, []);

  const colors = {
    success: { bg: 'rgba(16,185,129,0.15)',  border: 'rgba(16,185,129,0.35)',  text: '#10B981' },
    error:   { bg: 'rgba(244,63,94,0.15)',   border: 'rgba(244,63,94,0.35)',   text: '#F43F5E' },
    warning: { bg: 'rgba(245,158,11,0.15)',  border: 'rgba(245,158,11,0.35)',  text: '#F59E0B' },
    info:    { bg: 'rgba(99,102,241,0.15)',   border: 'rgba(99,102,241,0.35)',  text: '#818CF8' },
  };

  const ToastUI = toast
    ? React.createElement('div', {
        style: {
          position: 'fixed',
          top: 20,
          right: 20,
          zIndex: 99999,
          background: (colors[toast.type] || colors.success).bg,
          border: `1px solid ${(colors[toast.type] || colors.success).border}`,
          color: (colors[toast.type] || colors.success).text,
          borderRadius: 12,
          padding: '12px 20px',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          maxWidth: 380,
          fontSize: 14,
          fontWeight: 500,
          boxShadow: '0 4px 24px rgba(0,0,0,0.35)',
          lineHeight: 1.5,
          wordBreak: 'break-word',
          cursor: 'pointer',
          pointerEvents: 'auto',
        },
        onClick: () => setToast(null),
        role: 'alert',
      }, toast.msg)
    : null;

  return { showToast, ToastUI };
}
