import React, { useState, useEffect } from 'react';
import { useToast } from '../hooks/useToast';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import {
  ShoppingBag, Download, Search,
  Tag, User, BookOpen,
  ChevronRight, CreditCard, Loader2
} from 'lucide-react';
import { epreuveAPI, authAPI, paiementAPI } from '../services/api';
import BackNavBar from './BackNavBar';
import { useBackHandler } from '../hooks/useBackHandler';
import { getDashboardPathForRole } from '../utils/backHandler';
import { getStoredSession } from '../utils/authSession';
import '../Dashboard.css';

const Marketplace = () => {
  const navigate = useNavigate();
  const { showToast, ToastUI } = useToast();
  const [items, setItems] = useState([]);
  const [solde, setSolde] = useState(0);
  const [loading, setLoading] = useState(true);
  const [buyingId, setBuyingId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    chargerDonnees();
  }, []);

  useBackHandler(() => {
    const { role } = getStoredSession();
    navigate(getDashboardPathForRole(role), { replace: true });
    return true;
  }, [navigate]);

  const chargerDonnees = async () => {
    setLoading(true);
    try {
      const [epreuvesRes, profilRes] = await Promise.all([
        epreuveAPI.getAll(),
        authAPI.getProfile(),
      ]);
      const payants = (epreuvesRes.data || []).filter(
        (ep) => ep.typeAcces === 'PAYANT' && ep.prix > 0
      );
      setItems(payants);
      setSolde(profilRes.data?.solde ?? 0);
    } catch (err) {
      console.error('Erreur marketplace:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleBuy = async (item) => {
    setBuyingId(item.identifiantPublic);
    try {
      await epreuveAPI.pay(item.identifiantPublic);
      showToast("Achat réussi ! L'épreuve est maintenant accessible dans la bibliothèque.");
      chargerDonnees();
    } catch (err) {
      const msg = err.response?.data?.message || err.response?.data || 'Solde insuffisant ou erreur de paiement.';
      showToast(typeof msg === 'string' ? msg : "Impossible d'acheter cette ressource.", 'error');
    } finally {
      setBuyingId(null);
    }
  };

  const handleRecharge = async () => {
    const montant = window.prompt('Montant à recharger (XOF) :', '2000');
    if (!montant || isNaN(montant)) return;
    try {
      await paiementAPI.recharger(parseInt(montant, 10), 'TMONEY');
      showToast('Recharge simulée avec succès (mode développement).');
      chargerDonnees();
    } catch (err) {
      showToast('Erreur lors de la recharge.', 'error');
    }
  };

  const filteredItems = items.filter((item) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      item.titre?.toLowerCase().includes(q) ||
      item.matiere?.nom?.toLowerCase().includes(q) ||
      item.identifiantPublic?.toLowerCase().includes(q)
    );
  });

  const featured = filteredItems[0];

  return (
    <div className="marketplace-layout" style={{ background: 'var(--bg-main)', minHeight: '100vh', padding: '2rem 3rem' }}>
      {ToastUI}
      <BackNavBar label="Retour au dashboard" />
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '3rem', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <h1 style={{ fontSize: '2.5rem', fontWeight: '900', color: '#0F172A' }}>Marketplace Académique</h1>
          <p style={{ color: 'var(--text-muted)' }}>Épreuves et ressources payantes publiées par l'université.</p>
        </div>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
          <div className="balance-card" style={{ background: 'white', padding: '10px 20px', borderRadius: '15px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <CreditCard size={20} color="var(--primary)" />
            <div>
              <p style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: '700' }}>MON SOLDE</p>
              <p style={{ fontWeight: '800', color: 'var(--primary)' }}>{Math.round(solde).toLocaleString('fr-FR')} XOF</p>
            </div>
          </div>
          <button type="button" className="btn-primary" onClick={handleRecharge} style={{ background: 'var(--secondary)', color: 'var(--primary)' }}>
            Recharger
          </button>
        </div>
      </header>

      <div style={{ marginBottom: '2rem', position: 'relative', maxWidth: '400px' }}>
        <Search size={18} style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)', color: '#475569' }} />
        <input
          type="text"
          placeholder="Rechercher une ressource..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ width: '100%', padding: '12px 12px 12px 42px', borderRadius: '12px', border: '1px solid #E2E8F0', fontSize: '0.95rem' }}
        />
      </div>

      {featured && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          style={{ background: 'linear-gradient(135deg, #0284c7 0%, #0ea5e9 50%, #f97316 100%)', borderRadius: '40px', padding: '3rem', color: 'white', marginBottom: '3rem', position: 'relative', overflow: 'hidden' }}
        >
          <div style={{ maxWidth: '600px', position: 'relative', zIndex: 2 }}>
            <span style={{ background: 'rgba(255,204,0,0.2)', color: 'var(--secondary)', padding: '5px 15px', borderRadius: '50px', fontSize: '0.8rem', fontWeight: '800' }}>À LA UNE</span>
            <h2 style={{ fontSize: '2.5rem', fontWeight: '900', marginTop: '1rem', marginBottom: '1rem' }}>{featured.titre}</h2>
            <p style={{ fontSize: '1.1rem', opacity: 0.8, marginBottom: '2rem' }}>
              {featured.matiere?.nom || 'Ressource académique'} — {featured.prix} XOF
            </p>
            <button type="button" className="btn-primary" onClick={() => handleBuy(featured)} style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              Acheter maintenant <ChevronRight size={20} />
            </button>
          </div>
          <div style={{ position: 'absolute', right: '-50px', bottom: '-50px', opacity: 0.1 }}><ShoppingBag size={400} /></div>
        </motion.div>
      )}

      {loading ? (
        <div style={{ textAlign: 'center', padding: '4rem', color: '#475569' }}>
          <Loader2 size={40} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 1rem' }} />
          Chargement des ressources...
        </div>
      ) : filteredItems.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '4rem', background: 'white', borderRadius: '24px', border: '1px solid #E2E8F0' }}>
          <BookOpen size={48} color="#94A3B8" style={{ margin: '0 auto 1rem' }} />
          <p style={{ color: '#475569' }}>Aucune ressource payante disponible pour le moment.</p>
        </div>
      ) : (
        <div className="market-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '30px' }}>
          {filteredItems.map((item) => (
            <motion.div
              key={item.id}
              whileHover={{ scale: 1.02 }}
              style={{ background: 'white', borderRadius: '30px', padding: '2rem', boxShadow: 'var(--shadow-sm)', border: '1px solid #F1F5F9', position: 'relative' }}
            >
              <div style={{ position: 'absolute', top: '20px', right: '20px', background: 'rgba(14,165,233,0.1)', padding: '5px 12px', borderRadius: '50px', fontSize: '0.7rem', fontWeight: '800', color: '#0284c7', border: '1px solid rgba(14,165,233,0.25)' }}>
                {item.session || 'PAYANT'}
              </div>
              <div style={{ background: '#F8FAFC', width: '60px', height: '60px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '1.5rem' }}>
                <BookOpen color="var(--primary)" />
              </div>
              <h3 style={{ fontSize: '1.2rem', fontWeight: '800', marginBottom: '10px', color: '#0F172A' }}>{item.titre}</h3>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '0.5rem', color: 'var(--text-muted)', fontSize: '0.9rem' }}>
                <Tag size={16} /> <span>{item.matiere?.nom || 'Matière'}</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '1.5rem', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
                <User size={16} /> <span>{item.matiere?.filiere?.nom || 'UL'}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #F1F5F9', paddingTop: '1.5rem' }}>
                <div>
                  <p style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: '700' }}>PRIX</p>
                  <p style={{ fontSize: '1.5rem', fontWeight: '900', color: 'var(--primary)' }}>{item.prix} <span style={{ fontSize: '0.8rem' }}>XOF</span></p>
                </div>
                <button
                  type="button"
                  className="btn-primary"
                  disabled={buyingId === item.identifiantPublic}
                  onClick={() => handleBuy(item)}
                  style={{ padding: '12px 24px', borderRadius: '15px', display: 'flex', alignItems: 'center', gap: '8px' }}
                >
                  {buyingId === item.identifiantPublic ? <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} /> : <Download size={16} />}
                  Acheter
                </button>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Marketplace;
