import { useEffect } from 'react';
import { pushBackHandler } from '../utils/backHandler';

/**
 * Enregistre un handler pour le bouton RETOUR Android (Capacitor).
 * Le callback doit retourner true si le retour a été consommé.
 */
export function useBackHandler(handler, deps = []) {
  useEffect(() => {
    const unregister = pushBackHandler(handler);
    return unregister;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}
